import type { Difficulty, LegacyTrackId, Repository, ResearchTodo, Resource, ResourceType, TrackId } from "../domain/types";
import { SEED_TIME, VERIFIED_ON, seedId } from "./ids";

type R = {
  title: string;
  url: string;
  publisher: string;
  type: ResourceType;
  difficulty?: Difficulty;
  why: string;
  topics: string[];
  /** Legacy track ids (MS/CS/IT) are folded into AG when built. */
  tracks: (TrackId | LegacyTrackId)[];
  /** false when an automated reachability check was blocked (403) — needs a manual check */
  checked?: boolean;
  /** Seed version that introduced the entry; the data migration inserts only newer ones. */
  since?: number;
};

export const toAutonomyTrack = (t: string): TrackId => (t === "MS" || t === "CS" || t === "IT" ? "AG" : (t as TrackId));

