export const resourceId = (slug: string) => {
  if (!RESOURCE_SEED[slug]) throw new Error(`Unknown resource slug: ${slug}`);
  return seedId(`resource:${slug}`);
};

export function buildResources(): Resource[] {
  return Object.entries(RESOURCE_SEED).map(([slug, r]) => ({
    id: seedId(`resource:${slug}`),
    title: r.title,
    url: r.url,
    publisher: r.publisher,
    type: r.type,
    difficulty: r.difficulty ?? null,
    duration: null,
    why: r.why,
    topics: r.topics,
    trackIds: [...new Set(r.tracks.map(toAutonomyTrack))],
    lastVerified: r.checked === false ? null : VERIFIED_ON,
    addedBy: null,
    createdAt: SEED_TIME,
  }));
}

export function buildRepositories(): Repository[] {
  const repos: [string, string, string, string, string][] = [
    ["utahrobotics", "utah-lunabotics-2027", "main", "Utah Student Robotics", "Calibration tooling, MuJoCo arena, Godot operator base, onboarding guide."],
    ["PurdueLunabotics", "purdue_lunabotics", "master", "Purdue Lunabotics", "S-Theta* planner, Enum-based state machine, stall detection, PID control."],
    ["College-of-DuPage-Lunabotics", "lunabot_ros", "master", "College of DuPage", "robot_localization UKF, FAST-LIO/Point-LIO, Nav2 BTs, action servers, GUI."],
    ["GOFIRST-Robotics", "Lunabotics", "main", "GOFIRST (UMN)", "Slope costmap generator, AprilTag node, Gazebo NASA field, Nav2 config."],
  ];
  return repos.map(([owner, name, branch, team, description]) => ({
    id: seedId(`repo:${owner}/${name}`),
    owner,
    name,
    url: `https://github.com/${owner}/${name}`,
    team,
    defaultBranch: branch,
    description,
    kind: "reference" as const,
  }));
}

/** Videos and sources we deliberately did not invent. */
export function buildResearchTodos(): ResearchTodo[] {
  const todos: [string, string, TrackId | LegacyTrackId | null, ("open" | "done")?][] = [
    ["Select specific Kalman/EKF/UKF lecture videos", "Resolved: MATLAB 'Understanding Kalman Filters' series and Shane Ross Part 1 verified via oEmbed and added.", "SF", "done"],
    ["Select Articulated Robotics episodes for URDF → Gazebo → ros2_control", "Resolved: four Articulated Robotics episodes verified and linked to SIM-02 and AG-07.", "SIM", "done"],
    ["Select a verified Nav2 configuration walkthrough video", "Resolved: Robotics Back-End crash course and The Construct waypoint videos verified. An official Nav2/ROSCon talk is still worth adding.", "NV", "done"],
    ["Find a verified behavior-tree introduction talk", "Resolved: Davide Faconti's ROSDevCon19 talk and Petter Ögren's 5-minute tutorial verified.", "MS", "done"],
    ["Find verified material on LiDAR motion distortion (deskewing)", "Papers or lectures covering per-point timestamps and motion compensation for PM-02 / SF-03.", "PM"],
    ["Locate the current Lunabotics guidebook (2026–2027 cycle)", "Arena dimensions, zone layout and autonomy scoring must come from the official guidebook, not from other teams' code.", "SIM"],
    ["Verify OpenCV documentation deep links manually", "docs.opencv.org blocked automated checks (HTTP 403). Confirm in a browser and set the verified date.", "PM"],
    ["Research radar sensors suitable for dust (SF-05/SF-07)", "No verified radar reference implementation exists yet in the seeded repositories. (SF-07 radar detection is now PM-09.)", "SF"],
    ["Find a verified SLAM lecture series", "Resolved: Cyrill Stachniss's SLAM introduction and graph-SLAM lectures verified and added.", "SF", "done"],
    ["Verified videos for remaining advanced tasks", "PM-07, PM-08, AG-09, AG-11, AG-12 and AG-13 still have no topic-specific verified video. Verify URL + channel (oEmbed) before adding.", null],
    ["Obtain the Controls team's motion command contract", "AG-07 needs their message types, limits and fault codes. Tracked under External Dependencies.", "AG"],
  ];
  return todos.map(([topic, note, trackId, status]) => ({ id: seedId(`todo:${topic}`), topic, note, trackId: trackId ? toAutonomyTrack(trackId) : null, taskId: null, status: status ?? ("open" as const), createdAt: SEED_TIME }));
}
